def completar_maximo(apps, schema_editor):
    """Solicitudes anteriores: se recalcula el máximo con la misma tarifa con que se calculó el mínimo."""
    from web.precios import estimar
    Postulacion = apps.get_model("web", "Postulacion")
    for p in Postulacion.objects.filter(precio_sugerido__isnull=False, precio_sugerido_maximo__isnull=True):
        area = p.alto_cm * p.ancho_cm
        tamano = "pequeno" if area <= 25 else "mediano" if area <= 150 else "grande" if area <= 625 else "especial"
        e = estimar({"cobertura": p.cobertura, "tamano": tamano, "zona": p.zona_cuerpo, "color": p.color, "detalle": p.nivel_detalle})
        if not e["manual"] and e["minimo"] == p.precio_sugerido:  # solo si coincide con lo que vio el cliente
            p.precio_sugerido_maximo = e["maximo"]
            p.save(update_fields=["precio_sugerido_maximo"])


